diff --git a/cli/main.cpp b/cli/main.cpp
new file mode 100644
index 0000000..e8cbd10
--- /dev/null
+++ b/cli/main.cpp
@@ -0,0 +1,209 @@
+/*
+ *   SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+ *
+ *   SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only OR LicenseRef-KDE-Accepted-GPL
+ */
+
+#include <QCommandLineParser>
+#include <QCoreApplication>
+#include <QDir>
+#include <QSet>
+#include <QTextStream>
+#include <QTimer>
+
+#include <KLocalizedString>
+
+#include "plasmavault_interface.h"
+#include <common/vaultinfo.h>
+
+using namespace PlasmaVault;
+
+namespace
+{
+QTextStream out(stdout);
+QTextStream err(stderr);
+
+QString statusText(const VaultInfo &vault)
+{
+    switch (vault.status) {
+    case VaultInfo::Opened:
+        return i18nc("@info:status vault state", "unlocked");
+    case VaultInfo::Closed:
+        return i18nc("@info:status vault state", "locked");
+    case VaultInfo::Opening:
+        return i18nc("@info:status vault state", "unlocking");
+    case VaultInfo::Closing:
+        return i18nc("@info:status vault state", "locking");
+    case VaultInfo::DeviceMissing:
+        return i18nc("@info:status vault state", "missing");
+    default:
+        return i18nc("@info:status vault state", "unavailable");
+    }
+}
+
+// A vault can be referred to by its name, its mount point or its encrypted folder
+QList<VaultInfo> findVaults(const VaultInfoList &vaults, const QString &argument)
+{
+    QList<VaultInfo> result;
+    for (const auto &vault : vaults) {
+        if (vault.name == argument) {
+            result << vault;
+        }
+    }
+    if (!result.isEmpty()) {
+        return result;
+    }
+
+    const QString path = QDir::cleanPath(QDir::current().absoluteFilePath(argument));
+    for (const auto &vault : vaults) {
+        if (QDir::cleanPath(vault.mountPoint) == path || QDir::cleanPath(vault.device) == path) {
+            result << vault;
+        }
+    }
+    return result;
+}
+}
+
+int main(int argc, char *argv[])
+{
+    QCoreApplication app(argc, argv);
+    KLocalizedString::setApplicationDomain(TRANSLATION_DOMAIN);
+    app.setApplicationName(QStringLiteral("plasma-vault"));
+
+    QCommandLineParser parser;
+    parser.setApplicationDescription(i18n("Lock and unlock Plasma Vaults"));
+    parser.addHelpOption();
+    parser.addPositionalArgument(QStringLiteral("command"),
+                                 i18n("list: show all vaults\n"
+                                      "open <vault>: unlock a vault, asking for its password\n"
+                                      "close <vault>: lock a vault"));
+    parser.addPositionalArgument(QStringLiteral("vault"), i18n("The vault's name, mount point or encrypted folder"), QStringLiteral("[vault]"));
+    const QCommandLineOption allOption(QStringLiteral("all"), i18n("Lock all unlocked vaults"));
+    const QCommandLineOption forceOption(QStringLiteral("force"), i18n("Close applications using the vault before locking it"));
+    parser.addOption(allOption);
+    parser.addOption(forceOption);
+    parser.process(app);
+
+    const QStringList arguments = parser.positionalArguments();
+    const QString command = arguments.value(0);
+    const bool all = parser.isSet(allOption);
+    const bool force = parser.isSet(forceOption);
+
+    if ((command == QLatin1String("list") && arguments.size() != 1) || (command == QLatin1String("open") && arguments.size() != 2)
+        || (command == QLatin1String("close") && arguments.size() != (all ? 1 : 2))) {
+        parser.showHelp(1);
+    }
+    if (command != QLatin1String("list") && command != QLatin1String("open") && command != QLatin1String("close")) {
+        err << i18n("Unknown command: %1", command) << Qt::endl;
+        parser.showHelp(1);
+    }
+
+    org::kde::plasmavault service(QStringLiteral("org.kde.kded6"), QStringLiteral("/modules/plasmavault"), QDBusConnection::sessionBus());
+
+    QDBusReply<VaultInfoList> reply = service.availableDevices();
+    if (!reply.isValid()) {
+        err << i18n("Could not reach the Plasma Vault service: %1", reply.error().message()) << Qt::endl;
+        return 1;
+    }
+    const VaultInfoList vaults = reply.value();
+
+    if (command == QLatin1String("list")) {
+        for (const auto &vault : vaults) {
+            out << vault.name << '\t' << statusText(vault) << '\t' << vault.mountPoint << '\t' << vault.device << Qt::endl;
+        }
+        return 0;
+    }
+
+    QList<VaultInfo> targets;
+    if (all) {
+        for (const auto &vault : vaults) {
+            if (vault.isOpened()) {
+                targets << vault;
+            }
+        }
+    } else {
+        targets = findVaults(vaults, arguments.at(1));
+        if (targets.isEmpty()) {
+            err << i18n("No vault named or located at \"%1\"", arguments.at(1)) << Qt::endl;
+            return 1;
+        }
+        if (targets.size() > 1) {
+            err << i18n("More than one vault is named \"%1\"; use its mount point instead", arguments.at(1)) << Qt::endl;
+            return 1;
+        }
+    }
+
+    if (command == QLatin1String("open")) {
+        const auto &vault = targets.first();
+        if (vault.isOpened()) {
+            return 0;
+        }
+        // The password is never handled here: the service asks for it in its own dialog
+        service.openVault(vault.device).waitForFinished();
+        return 0;
+    }
+
+    // Locking happens in the background; wait for every vault to report the result
+    QSet<QString> pending;
+    QHash<QString, QString> failures;
+    int exitCode = 0;
+
+    QTimer failureTimer;
+    failureTimer.setSingleShot(true);
+    failureTimer.setInterval(2000);
+
+    const auto finish = [&] {
+        if (!pending.isEmpty() || failureTimer.isActive()) {
+            return;
+        }
+        app.exit(exitCode);
+    };
+
+    QObject::connect(&failureTimer, &QTimer::timeout, &app, [&] {
+        for (auto it = failures.cbegin(); it != failures.cend(); ++it) {
+            err << (it.value().isEmpty() ? i18n("Could not lock %1", it.key()) : i18n("Could not lock %1: %2", it.key(), it.value())) << Qt::endl;
+        }
+        failures.clear();
+        finish();
+    });
+
+    QObject::connect(&service, &org::kde::plasmavault::vaultChanged, &app, [&](const VaultInfo &vault) {
+        if (vault.status == VaultInfo::Closed) {
+            pending.remove(vault.device);
+            failures.remove(vault.name);
+        } else if (vault.status == VaultInfo::Opened && (pending.contains(vault.device) || failures.contains(vault.name))) {
+            // The reason for the failure can arrive shortly after the status
+            pending.remove(vault.device);
+            failures[vault.name] = vault.message;
+            exitCode = 1;
+            failureTimer.start();
+        }
+        finish();
+    });
+
+    for (const auto &vault : targets) {
+        if (vault.isOpened()) {
+            pending << vault.device;
+        }
+    }
+
+    const QSet<QString> devices = pending;
+    for (const auto &device : devices) {
+        if (force) {
+            service.forceCloseVault(device).waitForFinished();
+        } else {
+            service.closeVault(device).waitForFinished();
+        }
+    }
+
+    if (pending.isEmpty()) {
+        return 0;
+    }
+
+    QTimer::singleShot(60000, &app, [&] {
+        err << i18n("Timed out waiting for the vault to lock") << Qt::endl;
+        app.exit(1);
+    });
+
+    return app.exec();
+}
